<?php
declare(strict_types=1);
namespace DigiForge\Portal;
use DigiForge\POD\{PrintifyProductPipeline,Shop2ProductWorkflow,Shop2EtsyDraftHandoff};
use WP_Error;
/** The existing Shop 2 handler owns admission/nonces; no new REST or transport registration. */
final class Shop2ProviderProductPanel {
 public function process(array $post,array $link):array|WP_Error {
  if(!Shop2ProductWorkflow::access(true)||\DigiForge\Security\ShopAccess::authorize('personalized_pod','manage_digiforge_connections')!==true)return PrintifyProductPipeline::error('access');
  $package=$post['package_hash']??null;if(!is_string($package))return PrintifyProductPipeline::error('package');
  $raw=(new Shop2ProductWorkflow())->export($link,$package);if(is_wp_error($raw))return $raw;
  $op=$post['operation'];$pipe=new PrintifyProductPipeline();$out=['hash'=>$post['workflow_hash'],'supplier_workflow_hash'=>$link['hash'],'package_hash'=>$package];
  if(is_string($post['factory_hash']??null))$out['design_factory_hash']=$post['factory_hash'];
  if($op==='etsy_draft_prepare'){
   $id=$post['etsy_shop_id']??null;if(!is_string($id)||!preg_match('/^[1-9][0-9]{0,17}$/D',$id))return PrintifyProductPipeline::error('etsy_shop');
   $e=json_decode($raw,true);$shopId=(int)$id;global $wpdb;$wpdb->last_error='';$predicate=\DigiForge\Listings\EtsyStoredShopScope::matches($wpdb->prepare('%s','personalized_pod'),$wpdb->prepare('%s',$id),$wpdb->prepare('%s',$e['package']['environment']));$assigned=$wpdb->get_var('SELECT '.$predicate);
   if($wpdb->last_error!==''||(string)$assigned!=='1')return PrintifyProductPipeline::error('etsy_verified_shop_required');
   $decl=$this->json($post['provider_options']??null);if(is_wp_error($decl))return $decl;$handoff=Shop2EtsyDraftHandoff::prepare($e,$shopId,$decl);if(is_wp_error($handoff))return $handoff;$handoff['profile_ownership_status']='DECLARED_UNVERIFIED';$handoff['remaining_gates'][]='ETSY_PROFILE_OWNERSHIP_REQUIRED';
   return $out+['provider_export'=>json_encode($handoff,JSON_THROW_ON_ERROR|JSON_PRETTY_PRINT)];
  }
  if($op==='provider_prepare'){
   $id=$post['integration_id']??null;$operation=$post['provider_operation']??null;if(!is_string($id)||!preg_match('/^[1-9][0-9]{0,8}$/D',$id)||!is_string($operation))return PrintifyProductPipeline::error('typed');$options=$this->json($post['provider_options']??null);if(is_wp_error($options))return $options;$plan=$pipe->prepare($link['hash'],$package,(int)$id,$operation,$options);return is_wp_error($plan)?$plan:$out+['provider_plan_hash'=>$plan['hash']];
  }
  if($op==='provider_receipt'){$id=$post['provider_receipt_hash']??null;if(!is_string($id))return PrintifyProductPipeline::error('receipt');$r=$pipe->receipt($id);if(is_wp_error($r))return $r;if($r['workflow']!==$link['hash']||$r['package']!==$package)return PrintifyProductPipeline::error('receipt_scope');return $out+['provider_receipt_hash'=>$id];}
  $id=$post['provider_plan_hash']??null;if(!is_string($id))return PrintifyProductPipeline::error('plan');$p=$pipe->plan($id);if(is_wp_error($p))return $p;if($p['workflow']!==$link['hash']||$p['package']!==$package)return PrintifyProductPipeline::error('plan_scope');
  if($op==='provider_inspect')return $out+['provider_plan_hash'=>$id];
  if(($post['confirm']??null)!=='1')return PrintifyProductPipeline::error('explicit_confirmation');
  if($op==='provider_authorize'){$a=$pipe->authorize($id);return is_wp_error($a)?$a:$out+['provider_plan_hash'=>$id,'provider_authorization_hash'=>$a['hash']];}
  if($op==='provider_execute'&&is_string($post['provider_authorization_hash']??null)){$r=(new \DigiForge\POD\PrintifyControlledTransport())->executeProduct($id,$post['provider_authorization_hash']);return is_wp_error($r)?$r:$out+['provider_plan_hash'=>$id,'provider_receipt_hash'=>$r['hash']];}
  return PrintifyProductPipeline::error('operation');
 }
 private function json(mixed $raw):array|WP_Error {if(!is_string($raw)||strlen($raw)>65536)return PrintifyProductPipeline::error('options');try{$p=json_decode($raw,true,20,JSON_THROW_ON_ERROR);return is_array($p)&&($p===[]||!array_is_list($p))?$p:PrintifyProductPipeline::error('options_object');}catch(\Throwable){return PrintifyProductPipeline::error('options_json');}}
 public function render(array $link,string $research,string $base):void {
  if(!Shop2ProductWorkflow::access(true)||\DigiForge\Security\ShopAccess::authorize('personalized_pod','manage_digiforge_connections')!==true)return;$package=$_GET['df_package_version']??null;$design=$_GET['df_factory_version']??null;if(!is_string($package)||!is_string($design))return;
  $raw=(new Shop2ProductWorkflow())->export($link,$package);if(is_wp_error($raw))return;$e=json_decode($raw,true);$common=['supplier_workflow_hash'=>$link['hash'],'workflow_hash'=>$research,'factory_hash'=>$design,'package_hash'=>$package,'return_url'=>$base];
  echo '<section class="df-panel" id="df-provider-product"><h3>Printify API product preparation</h3><p>Prepare exact API requests locally. Live execution requires current reviewed product-scope ownership, separately reviewed exact operation policy, signed owner authorization and existing runtime controls. Catalog grants never authorize product mutations. No order or publish endpoint is admitted.</p>';
  $this->form('provider_prepare',$common);echo '<label>Configured Printify integration ID<input name="integration_id" type="number" min="1" required></label><label>Operation<select name="provider_operation">';foreach(['IMAGE_UPLOAD','IMAGE_READ','PRODUCT_CREATE','PRODUCT_READ','PRODUCT_UPDATE','PERSONALIZATION_OPTIONS','PERSONALIZATION_CONFIGURE','PREVIEW_CREATE','PREVIEW_READ'] as $op)echo '<option>'.esc_html($op).'</option>';echo '</select></label><label>Exact options JSON<textarea name="provider_options" maxlength="65536" rows="8" required>{}</textarea></label><button class="df-button">Prepare immutable API plan — no call</button></form>';
  echo '<details><summary>Operation inputs and honest capability boundaries</summary><p>Upload: {"asset_reference":"approved raster reference"}. The PNG must be part of the approved design and match catalog pixels. No automatic SVG conversion. Create: {"image_receipt":"SHA-256","price_minor":2500,"placement":{"x":0.5,"y":0.5,"scale":1,"angle":0}} — values are explicit operator choices, not inferred margins.</p><p>Read/update product: {"product_receipt":"SHA-256"}, plus price_minor for a full variant-preserving update. Native options: same product_receipt. Configure/preview: product_receipt, options_receipt, items, photo_receipts; preview also external_id and format. Text/photo field IDs and limits come from native options readback. Image URLs must equal same-package upload/read receipt URLs. Configure does not send buyer approval or any order.</p><p>Task status: product_receipt + preview_receipt. One explicit request at a time; no automatic polling/retry. Preview availability is provider/account dependent; 403 remains a real blocker. Native layer creation in the provider editor and unsupported setup remain manual. Receipt mockup URLs are observations until their image bytes are separately verified/imported.</p></details>';
  $this->form('provider_inspect',$common);echo '<label>Saved plan SHA-256<input name="provider_plan_hash" pattern="[a-f0-9]{64}" required></label><button class="df-button">Inspect saved plan</button></form>';
  $pipe=new PrintifyProductPipeline();$id=$_GET['df_provider_plan']??null;
  if(is_string($id)){$p=$pipe->plan($id);if(!is_wp_error($p)&&$p['workflow']===$link['hash']&&$p['package']===$package){$view=$p;unset($view['request']['body']['contents']);echo '<pre>'.esc_html((string)wp_json_encode($view,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</pre><p>Exact policy key: <code>'.esc_html('printify-product:'.$id).'</code></p><pre>'.esc_html((string)wp_json_encode($pipe->approvalPayload($id),JSON_PRETTY_PRINT)).'</pre>';
   foreach(['provider_authorize'=>'Issue one short-lived owner authorization','provider_execute'=>'Execute exactly one approved API operation'] as $op=>$label){$this->form($op,$common+['provider_plan_hash'=>$id]);if($op==='provider_execute')echo '<label>Authorization SHA-256<input name="provider_authorization_hash" value="'.esc_attr(is_string($_GET['df_provider_authorization']??null)?$_GET['df_provider_authorization']:'').'" pattern="[a-f0-9]{64}" required></label>';echo '<label><input type="checkbox" name="confirm" value="1" required>I confirm this exact request and its separate authority.</label><button class="df-button"'.(PrintifyProductPipeline::locked()?' disabled':'').'>'.esc_html($label).'</button></form>';}
  }}
  $this->form('provider_receipt',$common);echo '<label>Receipt SHA-256<input name="provider_receipt_hash" pattern="[a-f0-9]{64}" required></label><button class="df-button">Read current scoped receipt</button></form>';$receipt=$_GET['df_provider_receipt']??null;if(is_string($receipt)){$r=$pipe->receipt($receipt);if(!is_wp_error($r)&&$r['workflow']===$link['hash']&&$r['package']===$package)echo '<p>Receipt SHA-256: <code>'.esc_html($receipt).'</code></p><pre>'.esc_html((string)wp_json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</pre>';}
  echo '<h3>Etsy draft handoff — no submission</h3>';$this->form('etsy_draft_prepare',$common);echo '<label>Verified assigned Etsy shop ID<input name="etsy_shop_id" type="number" min="1" required></label><label>Explicit physical-listing metadata<textarea name="provider_options" rows="5" required>{"quantity":1,"who_made":"someone_else","when_made":"made_to_order","taxonomy_id":null,"shipping_profile_id":null,"readiness_state_id":null}</textarea></label><p>Supply actual IDs. Profile ownership remains an acceptance gate; unknown IDs cannot prepare a draft plan. Existing Etsy draft transport still requires its own authorization. No publish path is added.</p><button class="df-button">Download scoped Etsy draft operation plan</button></form></section>';
 }
 private function form(string $op,array $common):void {echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';foreach($common+['action'=>Shop2ProductWorkflowPanel::ACTION,'operation'=>$op,'shop_key'=>'personalized_pod'] as $k=>$v)echo '<input type="hidden" name="'.esc_attr($k).'" value="'.esc_attr($v).'">';wp_nonce_field(Shop2ProductWorkflowPanel::ACTION,'_df_workflow_nonce');}
}
